import { readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));

const cssFiles = [
  "src/styles/variables.css",
  "src/styles/layout.css",
  "src/styles/cards.css",
  "src/styles/dog-theme.css",
  "src/styles/calendar.css"
];

const banner = `/* Cute Obsidian Workbench styles
 * Generated by scripts/build-css.mjs.
 * Keep this file self-contained for BRAT/GitHub Release installs.
 */
`;

const bundledCss = cssFiles
  .map((file) => {
    const absolutePath = join(root, file);
    return `\n/* ${basename(file)} */\n${readFileSync(absolutePath, "utf8").trim()}\n`;
  })
  .join("\n");

writeFileSync(join(root, "styles.css"), `${banner}${bundledCss}`, "utf8");

console.log(`Bundled ${cssFiles.length} CSS files into styles.css`);
